/** Injected at build time by tsup (and by vitest's define) from package.json. */
declare const __CLI_VERSION__: string;
/** `templateSource.repository` in package.json: the GitHub `owner/repo` holding the templates. */
declare const __TEMPLATE_REPOSITORY__: string;
/** `templateSource.ref` in package.json: the git ref of that repository this release scaffolds from. */
declare const __TEMPLATE_REF__: string;
